-- math library and numeric edge cases.
print(math.pi > 3.14, math.huge > 1e300, math.maxinteger, math.mininteger)
print(math.abs(-3), math.abs(-3.5), math.abs(math.mininteger))
print(math.ceil(3.2), math.ceil(-3.2), math.floor(3.8), math.floor(-3.8))
print(math.ceil(3), math.floor(3.0))
print(math.fmod(7, 3), math.fmod(-7, 3), math.fmod(7, -3), math.fmod(7.5, 2))
print(math.modf(3.7), math.modf(-3.7), math.modf(3))
print(math.sqrt(16), math.sqrt(2) > 1.41)
print(math.exp(0), math.exp(1) > 2.71)
print(math.log(1), math.log(math.exp(1)))
print(math.log(8, 2), math.log(100, 10))
print(math.max(1, 5, 3), math.min(1, 5, 3))
print(math.max(1), math.min(1))
print(math.max(1, 1.5), math.min(1, 1.5))
print(pcall(math.max))
print(pcall(math.max, 1, "a"))
print(math.tointeger("3"), math.tointeger(3.0), math.tointeger("3.0"), math.tointeger(3.5))
print(math.type(math.tointeger(3.0)))
print(math.ult(1, 2), math.ult(2, 1), math.ult(-1, 1), math.ult(0, 0))
print(math.ult(math.mininteger, math.maxinteger))
print(pcall(math.ult, "1", 2))
print(math.fmod(1, 0), 1 % 0)
print(pcall(function() return 1 // 0 end))
print(pcall(function() return math.fmod(1, 0) end))
print(math.random(0, 0))
print(pcall(math.random, 3, 1))
print(pcall(math.random, 0))
print(pcall(math.random, "a", "b"))
math.randomseed(42)
local a = math.random(1000)
math.randomseed(42)
local b = math.random(1000)
print(a == b)
print(pcall(math.random, 1, 0))
print(math.random(5, 5))
print(pcall(math.floor, "x"))
print(pcall(math.abs))
print(pcall(math.log))
print(pcall(math.log, 1, 1))
print(math.sin(0), math.cos(0), math.tan(0))
print(math.asin(0), math.acos(1), math.atan(0))
print(math.atan(1, 1) > 0.78)

-- integer/float promotion
print(1 + 1, 1 + 1.0, 1.0 + 1, 1 * 2, 1 / 2, 3 // 2, 3.0 // 2)
print(math.type(1 + 1), math.type(1 + 1.0), math.type(2 ^ 31))
print(2 ^ 63, math.type(2 ^ 63))
print(("x"):rep(2) .. 1)
print(0 // 1, 0.0 // 1)
print(math.mininteger // -1, math.mininteger % -1)
print(-math.mininteger == -math.mininteger)
print(math.maxinteger // -1)
